/* derive narration chunks + estimated duration for every chapter */
SCENES.forEach(function (s) {
  s.chunks = splitChunks(s.narration);
  s.dur = s.duration || Math.max(6, s.chunks.reduce(function (a, c) { return a + c.dur; }, 0) + 0.7);
});

